import{_ as n,o as i,c as o,a2 as _}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Securing Data in Motion and at Rest- Quantifying End-to-End Encryption Perfo... V. Umrao & D. Parkes","description":"","frontmatter":{"title":"Securing Data in Motion and at Rest- Quantifying End-to-End Encryption Perfo... V. Umrao & D. Parkes","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["Ceph","Distributed Storage","Encryption","Performance Testing","Security"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Securing_Data_in_Motion_and_at_Rest_-_Quantifying_End-to-End_Encryption_Perfo..._V._Umrao_D._Parkes.md","filePath":"posts/2025/Securing_Data_in_Motion_and_at_Rest_-_Quantifying_End-to-End_Encryption_Perfo..._V._Umrao_D._Parkes.md","lastUpdated":1780459816000}'),e={name:"posts/2025/Securing_Data_in_Motion_and_at_Rest_-_Quantifying_End-to-End_Encryption_Perfo..._V._Umrao_D._Parkes.md"};function r(a,t,s,l,p,g){return i(),o("div",null,[...t[0]||(t[0]=[_("<p>会议纪要：</p><p>本次会议由IBM团队在Ceph Days活动中分享，主题为Ceph对象存储安全性与性能测试结果。主讲人Vikash和Daniel介绍了在安全加固环境下Ceph RGW的性能表现，包括加密传输、存储加密等不同配置下的基准测试结果。</p><p><strong>主要议题与讨论</strong>：</p><ol><li><p><strong>测试背景与目标</strong>：研究在保证企业级安全性的前提下，Ceph能否提供高性能的对象存储解决方案。关键指标包括TLS/SSL启用对客户端的影响、内部加密对CPU需求的影响以及S3服务器端加密带来的性能开销。</p></li><li><p><strong>测试环境配置</strong>：使用Dell全闪存X5D节点作为存储节点，Dell R760/R660作为客户端节点，网络带宽为100Gbps。集群规模包括4节点、8节点和12节点三种配置，使用Albeno版本Ceph和Hashicorp Vault密钥管理。</p></li><li><p><strong>关键测试结果</strong>：</p><ul><li><strong>扩展性测试</strong>：随着节点数增加，吞吐量几乎线性增长，CPU核心使用率随节点增加而降低。</li><li><strong>对象大小影响</strong>：大对象读取受网络带宽限制，小对象读取可达2ms低延迟，写入性能受CPU限制。</li><li><strong>纠删码 vs 副本</strong>：副本在所有测试场景中表现优于纠删码。</li><li><strong>安全性能影响</strong>：传输层加密（RGW SSL）性能损失可忽略不计；内部加密（Messenger V2）对性能影响极小；存储加密（SSE-S3）性能影响最大，主要问题在于密钥管理器频繁往返请求。</li></ul></li><li><p><strong>结论与建议</strong>：</p><ul><li>增加节点可线性提升性能。</li><li>小对象读取可达2ms低延迟。</li><li>推荐启用RGW SSL和Messenger V2，避免在HAproxy层做SSL终止，存储加密需权衡性能损失。</li><li>未来工作包括测试400G网络环境，优化HAproxy默认配置，验证Fast EC的实际改进效果。</li></ul></li><li><p><strong>行动计划</strong>：</p><ul><li>深入调查HAproxy SSL终止性能问题。</li><li>跟踪RGW存储加密优化进展。</li><li>扩展测试其他负载均衡方案。</li><li>在更高速网络环境下复现测试。</li></ul></li></ol>",4)])])}const u=n(e,[["render",r]]);export{c as __pageData,u as default};
